// Source of the "API" ModuleScript the bridge puts in CoreGui.AILabs. Plain Luau so any context can require it.
export const API_SOURCE = `--!strict
-- AI Labs agent API (generated by the AI Labs plugin, a UI Labs fork; see AGENTS.md)
--   local ui = require(game:GetService("CoreGui").AILabs.API)
--   ui.open("ui/crops/sell-page", { controls = { tab = "gear" }, capture = "phone" })
local invoke = script.Parent:WaitForChild("Invoke") :: BindableFunction

local function call(command: string, args: any?): any
	local response = invoke:Invoke(command, args or {})
	if not response.ok then
		error("[AI Labs] " .. tostring(response.error), 2)
	end
	return response.result
end

local ui = {}

-- Raw access: ui.call("open", { story = ... })
ui.call = call

function ui.status() return call("status") end
function ui.list(filter: string?) return call("list", { filter = filter }) end
-- open the AI Labs window (true) or close it (false); nil just reports
function ui.window(open: boolean?) return call("window", { open = open }) end
-- opts: widget (own window), show (open AI Labs window), controls, capture (preset/Vector2/{width,height}),
--       background (Color3), backgroundTransparency, timeout
function ui.open(story: string | ModuleScript, opts: { [string]: any }?)
	local args = table.clone(opts or {})
	args.story = story
	return call("open", args)
end
function ui.close(key: string?) return call("close", { key = key }) end
function ui.closeAll() return call("close", { key = "all" }) end
function ui.controls(key: string?) return call("controls", { key = key }) end
function ui.set(controls: { [string]: any }, key: string?) return call("set", { controls = controls, key = key }) end
function ui.reload(key: string?) return call("reload", { key = key }) end
-- capture: preset name ("fill", "phone", "phonePortrait", "tablet", "laptop", "desktop"), Vector2, {width, height},
-- or false to put the story back in the AI Labs window
function ui.capture(capture: any?, opts: { [string]: any }?)
	local args = table.clone(opts or {})
	args.capture = if capture == nil then "fill" else capture
	return call("capture", args)
end
-- turn on the Select Elements or Comment For AI tool ("select" | "comment" | "none")
function ui.tool(name: string?) return call("tool", { name = name }) end
function ui.zoom(zoom: number?, key: string?) return call("zoom", { zoom = zoom, key = key, reset = true }) end
-- GUI tree of the story (names, classes, rects relative to the story root, texts, images)
function ui.tree(opts: { [string]: any }?) return call("tree", opts or {}) end
function ui.logs(since: number?) return call("logs", { since = since }) end
-- comments people left with the Comment tool (unresolved; opts.all includes resolved, opts.story filters)
function ui.comments(opts: { [string]: any }?) return call("comments", opts or {}) end
function ui.resolveComment(id: string, resolved: boolean?) return call("resolveComment", { id = id, resolved = resolved }) end
function ui.deleteComments(opts: { [string]: any }) return call("deleteComments", opts) end

return ui
`;
